-- First editor: the HAND operator inbox, so the site can be tested before the
-- client's own email is added (admin Editors tab or LHWT_OWNER_EMAILS).
insert into command.lhwt_editors (email, role)
values ('hand@handprotocol.org', 'owner')
on conflict do nothing;
